def esc(s):
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
tpl = open(os.path.join(ROOT, 'scripts', 'label_template.svg')).read()
out_dir = os.path.join(ROOT, 'src', 'data', 'images')
os.makedirs(out_dir, exist_ok=True)

products = []

def add(pid, name, category, subcategory, brand, price, oldPrice, icon, desc, specs, stock=12, rating=4.6, reviews=24, tag=None):
    products.append({
        "id": pid, "sku": f"IM-{pid.upper()}", "name": name, "category": category,
        "subcategory": subcategory, "brand": brand, "price": price, "oldPrice": oldPrice,
        "image": f"/src/data/images/{pid}.svg", "iconType": icon,
        "description": desc, "specs": specs, "inStock": True, "stock": stock,
        "rating": rating, "reviews": reviews, "tag": tag,
        "status": "active", "createdAt": "2026-10-01T00:00:00.000Z",
    })
    svg = (tpl.replace('__ICON__', ICONS[icon])
              .replace('__BRAND__', esc(brand))
              .replace('__MODEL__', esc(name)))
    with open(f'{out_dir}/{pid}.svg', 'w') as f:
        f.write(svg)

